with flagged as (select *, case when txn_time - lag(txn_time) over (partition by txn_type order by txn_time, id) > interval 90 days then 1 else 0 end as is_new_burst from transactions), sessions_transactions as (select *, sum(is_new_burst) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as session_id from flagged) select session_id, count_if(txn_type = 'REFUND') as refund_events, count(case when txn_type = 'FEE' then 1 end) as fee_count, round(sum(amount) / nullif(count(case when merchant = 'Shell' then 1 end), 0), 2) as amount_per_shell, round(sum(amount) / nullif(count(case when txn_type = 'FEE' then 1 end), 0), 2) as amount_per_fee, size(collect_set(txn_type)) as num_txn_types from sessions_transactions group by session_id
